head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > mandatory]<br/>컴포넌트의 유효성 체크 시 입력값 유무 여부를 확인하도록 설정합니다.",
    "validation" : [
        "validateObject() 메소드로 실행하여 유효성 체크를 수행합니다.",
        "미설정 시 컴포넌트의 입력값 유무를 확인하지 않습니다.",
        "true 설정 시 컴포넌트의 입력값 유무를 확인합니다.",
        "true 설정 시 'w2input_mandatory' 형태와 같이 mandatory 클래스가 적용됩니다.",
        "false 설정 시 컴포넌트의 컴포넌트의 입력값 유무를 확인하지 않습니다.",
        "컴포넌트에 입력값이 없는 경우 유효성 체크는 실패로 처리되고 '필수 입력 항목입니다' 오류 메시지가 출력됩니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
	let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {        
        displaymessage: true,
        chooseOption: true,
        mandatory: wf_sample.getObj("con_mandatory").getText(),
    };

    let cList = $c.gcm.createCList(properties);       

    $c.gcm.createBasicCheckComboBox(cList);
}
